"""Regenerates the dark theme block at the end of src/style.css.

Every rule with a literal color gets a :root[data-theme="dark"] override whose lightness is
flipped according to the property: light surfaces turn dark, dark text turns light, and
saturated mid tones (buttons, badges' accents) keep their color. Run after changing colors:
    python scripts/dark_theme.py && npx prettier --write src/style.css
"""

import colorsys
import re
from pathlib import Path

CSS = Path(__file__).resolve().parent.parent / "src" / "style.css"
MARKER = (
    "/* ==== dark theme: generated by scripts/dark_theme.py, do not edit below ==== */"
)
DARK = ':root[data-theme="dark"]'
COLOR = re.compile(r"#[0-9a-fA-F]{6}\b|#[0-9a-fA-F]{3}\b|\bwhite\b")
URL = re.compile(r"url\([^)]*\)")
PAINT = re.compile(
    r"^(color|background(-color)?|border(-(top|right|bottom|left))?(-color)?"
    r"|outline(-color)?|fill|stroke|box-shadow)$"
)


def parse_hex(token):
    if token == "white":
        return 1.0, 1.0, 1.0
    h = token[1:]
    if len(h) == 3:
        h = "".join(c * 2 for c in h)
    return tuple(int(h[i : i + 2], 16) / 255 for i in (0, 2, 4))


def to_hex(rgb):
    return "#" + "".join(f"{round(max(0, min(1, c)) * 255):02x}" for c in rgb)


def flip(token, prop):
    r, g, b = parse_hex(token)
    hue, light, sat = colorsys.rgb_to_hls(r, g, b)
    if prop == "color" or prop in ("fill", "stroke", "caret-color", "accent-color"):
        if light >= 0.5:
            return token  # already light: white on buttons, pale accents
        light = 0.92 - light * 0.5
    elif prop.startswith(("border", "outline")):
        if light <= 0.5:
            return token
        light = 0.2 + (1 - light) * 0.8
    else:  # backgrounds and anything else painted as a surface
        if light <= 0.6:
            return (
                token  # saturated or dark surfaces (buttons, accents) keep their color
            )
        if token in ("white", "#fff", "#ffffff"):
            return "#1b2433"  # cards sit a step above the page background
        light = 0.08 + (1 - light) * 1.2
        sat = min(sat, 0.5)
    return to_hex(colorsys.hls_to_rgb(hue, light, sat))


def blocks(text):
    """Yields (prelude, body) for each top-level block, bodies kept raw."""
    i, depth, start, prelude = 0, 0, 0, ""
    while i < len(text):
        c = text[i]
        if c == "{":
            if depth == 0:
                prelude, start = text[start:i].strip(), i + 1
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                yield prelude, text[start:i]
                start = i + 1
        i += 1


def scope(selectors):
    out = []
    for s in selectors.split(","):
        s = s.strip()
        out.append(DARK + s[5:] if s.startswith(":root") else f"{DARK} {s}")
    return ", ".join(out)


def rules(text):
    lines = []
    for prelude, body in blocks(text):
        # Hand-written dark rules (above the marker) are already dark.
        if prelude.startswith(("@keyframes", "@font-face", DARK)):
            continue
        if prelude.startswith("@"):
            inner = rules(body)
            if inner:
                lines.append(prelude + " {\n" + inner + "\n}")
            continue
        changed = []
        for decl in body.split(";"):
            if ":" not in decl:
                continue
            prop, value = (p.strip() for p in decl.split(":", 1))
            # Every paint declaration is repeated, changed or not: the dark rules are more
            # specific, so a missing one would let a base :hover lose to a dark base rule.
            if not PAINT.match(prop) or URL.search(value):
                continue
            new = COLOR.sub(lambda m, p=prop: flip(m.group(0), p), value)
            changed.append(f"  {prop}: {new};")
        if changed:
            lines.append(scope(prelude) + " {\n" + "\n".join(changed) + "\n}")
    return "\n".join(lines)


def main():
    source = CSS.read_text(encoding="utf-8").split(MARKER)[0].rstrip() + "\n"
    clean = re.sub(r"/\*.*?\*/", "", source, flags=re.DOTALL)
    generated = rules(clean)
    CSS.write_text(f"{source}\n{MARKER}\n{generated}\n", encoding="utf-8")


if __name__ == "__main__":
    assert flip("white", "background") == "#1b2433"
    assert flip("white", "color") == "white"
    assert flip("#15283f", "color") > "#c"  # dark text turns light
    assert flip("#174dcc", "background") == "#174dcc"
    main()
